},
.function => |f| {
_ = bun.bits.insert(ColorFallbackKind, (&fallbacks), f.arguments.getNecessaryFallbacks(targets));
},
.@"var" => |v| {
if (v.fallback) |*fallback| {
                    _ = &fallback;
                    _ = bun.bits.insert(ColorFallbackKind, (&fallbacks), (fallback.*).getNecessaryFallbacks(targets));
                }
},
.env => |v| {
if (v.fallback) |*fallback| {
