pub fn toCss(self: EnvironmentVariable, dest: *Printer, is_custom_property: bool) PrintErr!void {
            _ = try dest.writeStr("env(");
            _ = try self.name.toCss(dest);
            for (self.indices.items) |index| {
                _ = &index;
                _ = try dest.writeChar(32);
                _ = try css.to_css.integer(i32, index, dest);
            }
            if (self.fallback) |*fallback| {
                _ = &fallback;
                _ = try dest.delim(44, false);
                _ = try (fallback.*).toCss(dest, is_custom_property);
            }
            return try dest.writeChar(41);
    }

pub fn getFallback(self: EnvironmentVariable, allocator: Allocator, kind: ColorFallbackKind) @This() {
            var fallback_val: ?TokenList = null;
            _ = &fallback_val;
            if (self.fallback) |fallback| {
                _ = &fallback;
                fallback_val = fallback.getFallback(allocator, kind);
            }
            return EnvironmentVariable{ .name = self.name, .indices = bun.handleOom(self.indices.clone(allocator)), .fallback = fallback_val };
    }

pub fn eql(lhs: *const @This(), rhs: *const @This()) bool {
            return css.implementEql(@This(), lhs, rhs);
    }

pub fn hash(val: *const @This(), hasher: *std.hash.Wyhash) void {
            return css.implementHash(@This(), val, hasher);
    }

pub fn deepClone(self: EnvironmentVariable, allocator: Allocator) EnvironmentVariable {
            var fallback_val: ?TokenList = null;
            _ = &fallback_val;
            if (self.fallback) |fallback| {
                _ = &fallback;
                fallback_val = fallback.deepClone(allocator);
            }
            return EnvironmentVariable{ .name = self.name, .indices = bun.handleOom(self.indices.clone(allocator)), .fallback = fallback_val };
    }
};

pub const Function = struct {
    name: Ident,
    arguments: TokenList,

pub fn deinit(self: *Function, allocator: Allocator) void {
            _ = self.arguments.deinit(allocator);
    }

pub fn toCss(self: Function, dest: *Printer, is_custom_property: bool) PrintErr!void {
            _ = try IdentFns.toCss((&self.name), dest);
            _ = try dest.writeChar(40);
            _ = try self.arguments.toCss(dest, is_custom_property);
            return try dest.writeChar(41);
    }

pub fn eql(lhs: *const @This(), rhs: *const @This()) bool {
            return css.implementEql(@This(), lhs, rhs);
    }

pub fn hash(val: *const @This(), hasher: *std.hash.Wyhash) void {
            return css.implementHash(@This(), val, hasher);
    }

pub fn deepClone(self: Function, allocator: Allocator) Function {
            return .{ .name = self.name, .arguments = self.arguments.deepClone(allocator) };
    }

pub fn getFallback(self: Function, allocator: Allocator, kind: ColorFallbackKind) @This() {
            return Function{ .name = self.name.deepClone(allocator), .arguments = self.arguments.getFallback(allocator, kind) };
    }
    const This = @This();
};

pub const UnparsedProperty = struct {
    property_id: css.PropertyId,
    value: TokenList,

