    }

pub fn getPrefixed(self: UnparsedProperty, allocator: Allocator, targets: css.Targets, feature: css.prefixes.Feature) UnparsedProperty {
            var clone = self.deepClone(allocator);
            _ = &clone;
            const prefix = self.property_id.prefix();
            clone.property_id = clone.property_id.withPrefix(targets.prefixes(prefix.orNone(), feature));
            return clone;
    }

pub fn withPropertyId(self: UnparsedProperty, allocator: Allocator, property_id: css.PropertyId) UnparsedProperty {
            return UnparsedProperty{ .property_id = property_id, .value = self.value.deepClone(allocator) };
    }

pub fn deepClone(self: UnparsedProperty, allocator: Allocator) @This() {
